        book[order_id] = {'side': side, 'price': price, 'qty': qty, 'active': True, 'seq': seq}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, order_id))
        else:
            heapq.heappush(sell_heap, (price, seq, order_id))

    def pop_best_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['side'] != 'buy':
                heapq.heappop(buy_heap)
                continue
            return negprice, seq, oid
        return None

    def pop_best_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['side'] != 'sell':
                heapq.heappop(sell_heap)
                continue
            return price, seq, oid
        return None

