        while remaining > 0:
            if incoming_side == 'buy':
                top = pop_best_sell()
                if top is None:
                    break
                price, seq, oid = top
                if not is_market and price > incoming_price:
                    break
                info = book[oid]
                trade_qty = min(remaining, info['qty'])
